// One item per <entry>. Adjust key names if your XML node strips the tna:/atom prefixes.
function asArray(x){ return x == null ? [] : (Array.isArray(x) ? x : [x]); }
function linkHref(links, type){
  const L = asArray(links);
  const hit = L.find(l => (l?.type ?? l?.['@type'] ?? l?.['$']?.type) === type);
  return hit?.href ?? hit?.['@href'] ?? hit?.['$']?.href ?? null;
}
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const links = e.link;
  const ids = asArray(e['tna:identifier'] ?? e.identifier);
  const html_url = asArray(links).find(l =>
      (l?.rel ?? l?.['@rel'] ?? l?.['$']?.rel) === 'alternate' &&
      !(l?.type ?? l?.['@type'] ?? l?.['$']?.type)
    )?.href
    ?? asArray(links).find(l => (l?.rel ?? l?.['@rel'] ?? l?.['$']?.rel) === 'alternate')?.href
    ?? null;
  out.push({ json: {
    document_uri:    e['tna:uri'] ?? e.uri ?? null,
    entry_id:        e.id ?? null,
    case_name:       e.title ?? null,
    court:           e.author?.name ?? null,
    published_at:    e.published ?? null,
    feed_updated_at: e.updated ?? null,
    content_hash:    e['tna:contenthash'] ?? e.contenthash ?? null,
    html_url,
    xml_url:         linkHref(links, 'application/akn+xml'),
    pdf_url:         linkHref(links, 'application/pdf'),
    identifiers: ids.map(i => ({
      type:  i?.['@type'] ?? i?.type ?? i?.['$']?.type ?? null,
      value: i?.['#'] ?? i?.['_'] ?? i?.value ?? (typeof i === 'string' ? i : null),
      slug:  i?.['@slug'] ?? i?.slug ?? i?.['$']?.slug ?? null
    })),
    scan_run_id:    $('Open Scan Run').first().json.scan_run_id,
    retrieved_at:   new Date().toISOString(),
    feed_page:      1,
    request_params: { order: '-date', per_page: 5, source: 'atom.xml' }
  }});
}
return out;

const out = [];
const items = $input.all();

function attr(xml, tag, name) {
  const m = xml.match(new RegExp(`<${tag}\\b[^>]*\\b${name}\\s*=\\s*"([^"]*)"`, 'i'));
  return m ? m[1] : null;
}
function el(xml, tag) {
  const m = xml.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)</${tag}>`, 'i'));
  return m ? m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : null;
}
function elAll(xml, tag) {
  const re = new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)</${tag}>`, 'gi');
  const res = []; let m;
  while ((m = re.exec(xml)) !== null) {
    const v = m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (v) res.push(v);
  }
  return res;
}
function frbrDate(xml, name) {
  const m = xml.match(new RegExp(`<FRBRdate\\b[^>]*\\bname\\s*=\\s*"${name}"[^>]*>`, 'i'));
  if (!m) return null;
  const d = m[0].match(/\bdate\s*=\s*"([^"]*)"/i);
  return d ? d[1] : null;
}

for (let i = 0; i < items.length; i++) {
  const xml = String(items[i].json.data ?? items[i].json.body ?? items[i].json.text ?? '');
  const text = xml
    .replace(/<[^>]+>/g, ' ')
    .replace(/&#\d+;|&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const meta = $('Normalise Feed Fields').itemMatching(i).json;

  // --- Layer 2a: deterministic LegalDocML (TNA AKN). Verify tag names against one real data.xml. ---
  const neutral_citation    = el(xml, 'uk:cite') ?? el(xml, 'neutralCitation') ?? null;
  const court_chamber       = el(xml, 'uk:court') ?? null;
  const judgment_date       = frbrDate(xml, 'judgment');
  const frbr_transform_date = frbrDate(xml, 'transform');
  const uk_hash             = el(xml, 'uk:hash') ?? meta.content_hash ?? null;
  const case_name_xml       = attr(xml, 'FRBRname', 'value');
  const party_names         = elAll(xml, 'party');
  const judge_names         = elAll(xml, 'judge');

  out.push({ json: {
    ...meta,
    judgment_text: text,
    fetch_status: text.length < 500 ? 'thin' : 'ok',
    neutral_citation:  neutral_citation ?? 'unknown',
    court_chamber:     court_chamber ?? 'unknown',
    judgment_date,                 // null if absent (date column)
    frbr_transform_date,           // null if absent
    uk_hash,
    case_name_xml:     case_name_xml ?? 'unknown',
    party_names,                   // [] if none
    judge_names                    // [] if none
  }});
}
return out;

const TOPICS = $('Load Topic Config').all().map(r => {
  const kw = typeof r.json.keywords === 'string' ? JSON.parse(r.json.keywords) : (r.json.keywords || {});
  return {
    topic_id: r.json.topic_id,
    topic_name: r.json.topic_name,
    conclusive: (kw.conclusive || []).map(s => s.toLowerCase()),
    supporting: (kw.supporting || []).map(s => s.toLowerCase())
  };
});
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  const hay = ` ${(c.judgment_text || '').toLowerCase()} `;
  const hayTokens = new Set(hay.split(/[^a-z0-9]+/).filter(Boolean));
  function termHits(term) {
    const parts = term.split(/\s+/).filter(Boolean);
    if (parts.length === 1) return hayTokens.has(parts[0]) ? 1 : 0;
    return parts.every(p => hayTokens.has(p)) ? 1 : 0;   // phrase: all words present, order-independent
  }
  const matched_topics = [], matched_terms = [];
  for (const t of TOPICS) {
    let conc = 0, supp = 0;
    for (const term of t.conclusive) { const n = termHits(term); if (n>0){ conc+=n; matched_terms.push({topic_id:t.topic_id, topic_name:t.topic_name, term, kind:'conclusive', hits:n}); } }
    for (const term of t.supporting) { const n = termHits(term); if (n>0){ supp+=n; matched_terms.push({topic_id:t.topic_id, topic_name:t.topic_name, term, kind:'supporting', hits:n}); } }
    if (conc > 0) matched_topics.push({ topic_id:t.topic_id, topic_name:t.topic_name, conclusive_hits:conc, supporting_hits:supp });
  }
  const pass = matched_topics.length > 0;   // gate = presence of a conclusive term
  out.push({ json: { ...c,
    matched_topics, matched_terms,
    filter_verdict: pass ? 'pass' : 'fail',
    filter_reason: pass
      ? `Matched conclusive terms in: ${matched_topics.map(m=>m.topic_name).join(', ')}`
      : 'No conclusive topic terms found in full text',
    criteria_evaluated: TOPICS.map(t => ({ topic_id:t.topic_id, topic_name:t.topic_name, conclusive_terms:t.conclusive.length, supporting_terms:t.supporting.length }))
  }});
}
return out;

