const S = { high: 3, medium: 2, low: 1, unknown: 0 };

// ~4 chars/token is the standard rough approximation for GPT models.
const estTokens = (s) => Math.ceil((String(s || '').length) / 4);
// Fixed instruction block sent with every call (the static rules in the AI Agent node).
// Measured once; judgment_text dominates, so a constant here is accurate enough.
const PROMPT_INSTRUCTION_TOKENS = 380;

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const src = $('Keyword Scan').itemMatching(i).json;
  const aiJson = items[i].json;

  let pack;
  try {
    pack = JSON.parse(String(aiJson.output ?? aiJson.text ?? '')
      .replace(/```json|```/g, '').trim());
  } catch {
    pack = { components:{}, keywords:[], legal_issue_type:'unknown',
             tier_reasoning:'parse_error', classification_confidence:'low' };
  }

  const comp = pack.components || {};
  const li = S[comp.legal_issue_tag?.score] ?? 0;
  const wr = S[comp.wider_relevance?.score]  ?? 0;
  const oc = S[comp.outcome_clarity?.score]  ?? 0;
  const score = li + wr + oc;                        // 0..9

  let tier = 'Red';
  if (li >= 3 && (wr >= 2 || oc >= 2)) tier = 'Green';
  else if (score >= 3)                 tier = 'Amber';
  const tier_bucket = tier === 'Green' ? 'top_slice' : tier === 'Amber' ? 'watch' : 'drop';

  const conf    = pack.classification_confidence || 'low';
  const lowConf = (conf === 'low');
  const highRel = (tier === 'Green');
  const lowRel  = (tier === 'Red');

  let routing_bucket;
  if (highRel) {
    routing_bucket = lowConf ? 'escalate' : 'fast_track';   // low conf promotes to priority check
  } else if (lowRel) {
    routing_bucket = lowConf ? 'quick_glance' : 'auto_drop';
  } else {
    routing_bucket = 'quick_glance';                        // Amber/watch: surface briefly
  }

  // tokens_used: use real usage if the agent surfaced it, otherwise estimate.
  const usage = aiJson.tokenUsage || aiJson.usage ||
                aiJson.response?.usage || aiJson.llmOutput?.tokenUsage || null;
  let tokens_used = usage?.totalTokens ?? usage?.total_tokens ?? null;

  if (tokens_used == null) {
    const topicsStr = (src.matched_topics || []).map(m => m.topic_name).join(', ');
    const promptTokens = PROMPT_INSTRUCTION_TOKENS
      + estTokens(src.case_name) + estTokens(src.court)
      + estTokens(topicsStr) + estTokens(src.judgment_text);
    const completionTokens = estTokens(aiJson.output ?? aiJson.text ?? '');
    tokens_used = promptTokens + completionTokens;
  }

  out.push({ json: {
    ...src,
    components: pack.components || {},
    keywords: Array.isArray(pack.keywords) ? pack.keywords : [],
    legal_issue_type: pack.legal_issue_type || 'unknown',
    tier_reasoning: pack.tier_reasoning || '',
    classification_confidence: conf,
    aggregate_score: score,
    relevance_tier: tier,          // Green|Amber|Red (text column)
    tier_bucket: tier_bucket,      // top_slice|watch|drop (tier enum)
    routing_bucket: routing_bucket,// §7 matrix (routing_bucket enum)
    tokens_used: tokens_used,      // real if available, else estimate
    confidence_signals: {
      text_thin: src.fetch_status === 'thin',
      classification_confidence: conf
    },
    model_version: 'gpt-5-mini',
    prompt_version: 'relevance-2026-07-20-a'
  }});
}
return out;

// weights_version per topic, from topics_config
const wByTopic = {};
for (const r of $('Load Topic Config').all()) {
  wByTopic[r.json.topic_name] = r.json.weights_version ?? null;
}

const out = [];
for (const item of $input.all()) {
  const c = item.json;
  for (const t of (c.matched_topics || [])) {
    out.push({ json: {
      document_uri:       c.document_uri,
      topic_id:           Number(t.topic_id),                      // integer
      components:         c.components || {},                       // object -> stringify at INSERT
      aggregate_score:    Number(c.aggregate_score) || 0,           // integer
      weights_version:    wByTopic[t.topic_name] ?? null,
      tier_bucket:        c.tier_bucket,                           // top_slice|watch|drop -> tier enum
      confidence_signals: c.confidence_signals || {},               // object -> stringify at INSERT
      model_version:      c.model_version,
      prompt_version:     c.prompt_version,
      relevance_tier:     c.relevance_tier,                        // Green|Amber|Red (text)
      tier_reasoning:     c.tier_reasoning || '',
      keywords:           Array.isArray(c.keywords) ? c.keywords : [], // array -> join at INSERT
      legal_issue_type:   c.legal_issue_type || 'unknown',
      tokens_used:        (c.tokens_used == null ? null : Number(c.tokens_used)),
      routing_bucket:     c.routing_bucket                         // §7 matrix -> routing_bucket enum
    }});
  }
}
return out;

const out = [];
for (const item of $input.all()) {
  const c = item.json;
  for (const t of (c.matched_topics || [])) {
    const terms = (c.matched_terms || []).filter(m => m.topic_id === t.topic_id);
    out.push({ json: {
      document_uri: c.document_uri,
      topic_id: Number(t.topic_id),
      matched_terms: terms
    }});
  }
}
return out;

