INSERT INTO case_topics (document_uri, topic_id, matched_terms)
VALUES ($1, $2, $3::text[])
ON CONFLICT (document_uri, topic_id) DO UPDATE SET matched_terms = EXCLUDED.matched_terms;

INSERT INTO decision_events (document_uri, layer, decision, reason, actor, event_at, metadata)
SELECT $1, 'ingest', 'ingested', NULL, 'system', $2::timestamptz, $3::jsonb
WHERE NOT EXISTS (
  SELECT 1 FROM decision_events
  WHERE document_uri = $1 AND layer = 'ingest'
);
